style.css:
@-moz-document domain("google.com") {
/* Global reset */
  html, body {
    height: 100% !important;
    margin: 0 !important;
    padding: 0 !important;
    background: transparent !important;
    overflow-x: hidden !important;
  }

  /* --- Background Animation --- */
  html::before {
    content: "";
    position: fixed;
    inset: 0;
    z-index: -2;
    background: url("https://e0.pxfuel.com/wallpapers/24/859/desktop-wallpaper-mine-akame-ga-kill.jpg")
      no-repeat center center fixed;
    background-size: cover;
    animation: bgZoom 40s ease-in-out infinite alternate;
    filter: brightness(0.9) contrast(1.05) saturate(1.2);
    pointer-events: none;
  }

  /* Smooth fade overlay for depth */
  html::after {
    content: "";
    position: fixed;
    inset: 0;
    z-index: -1;
    background: radial-gradient(circle at center, rgba(0, 0, 0, 0.3), rgba(0, 0, 0, 0.7));
    animation: fadeOverlay 8s ease-in-out infinite alternate;
    pointer-events: none;
  }

  /* --- Search box glow + animation --- */
  .RNNXgb {
    background: rgba(255, 255, 255, 0.1) !important;
    backdrop-filter: blur(10px) !important;
    border-radius: 20px !important;
    box-shadow: 0 0 25px rgba(255, 0, 70, 0.3), 0 0 45px rgba(255, 0, 70, 0.1);
    transition: all 0.4s ease-in-out !important;
    animation: fadeIn 2s ease-in-out 0.5s both;
  }

  .RNNXgb:hover {
    box-shadow: 0 0 30px rgba(255, 0, 100, 0.5), 0 0 60px rgba(255, 0, 100, 0.2);
    transform: scale(1.02);
  }

  /* --- Google logo animation --- */
  #hplogo, .lnXdpd {
    animation: logoFadeIn 2.5s ease-in-out both;
    filter: drop-shadow(0 0 15px rgba(255, 255, 255, 0.5));
    transition: transform 0.6s ease-in-out;
  }

  #hplogo:hover, .lnXdpd:hover {
    transform: scale(1.05) rotate(1deg);
    filter: drop-shadow(0 0 25px rgba(255, 50, 100, 0.7));
  }

  /* --- Buttons styling --- */
  .gNO89b, .RNmpXc {
    background: rgba(255, 255, 255, 0.15) !important;
    border: 1px solid rgba(255, 255, 255, 0.3) !important;
    color: #fff !important;
    text-shadow: 0 0 6px rgba(255, 0, 100, 0.4);
    border-radius: 12px !important;
    backdrop-filter: blur(6px) !important;
    transition: all 0.3s ease-in-out;
    animation: fadeInUp 2s ease-in-out 1s both;
  }

  .gNO89b:hover, .RNmpXc:hover {
    background: rgba(255, 0, 100, 0.4) !important;
    box-shadow: 0 0 25px rgba(255, 0, 100, 0.6);
    transform: translateY(-2px) scale(1.05);
  }

  /* --- Keyframes --- */
  @keyframes bgZoom {
    0%   { transform: scale(1) translateY(0); }
    100% { transform: scale(1.08) translateY(-10px); }
  }

  @keyframes fadeOverlay {
    0%   { opacity: 0.3; }
    100% { opacity: 0.6; }
  }

  @keyframes fadeIn {
    0%   { opacity: 0; transform: scale(0.95); }
    100% { opacity: 1; transform: scale(1); }
  }

  @keyframes fadeInUp {
    0%   { opacity: 0; transform: translateY(20px); }
    100% { opacity: 1; transform: translateY(0); }
  }

  @keyframes logoFadeIn {
    0%   { opacity: 0; transform: scale(0.8); }
    100% { opacity: 1; transform: scale(1); }
  }
}
